mapper.insert:
INSERT INTO adoption (
    user_id, pet_id, adopter_name, phone, economic_status, reason, status, apply_time
) VALUES (
    #{userId}, #{petId}, #{adopterName}, #{phone}, #{economicStatus}, #{reason}, 1, NOW()
)

mapper.select:
SELECT a.*, u.username, p.pet_name, p.photo as pet_photo, p.species as pet_species, p.breed as pet_breed FROM adoption a LEFT JOIN user u ON a.user_id = u.user_id LEFT JOIN pet p ON a.pet_id = p.pet_id
AND a.status = #{status}
ORDER BY a.apply_time DESC
